css:
.fx-faixa { display: grid; background: var(--bg); }
.fx-faixa + .fx-faixa { border-top: 1px solid var(--border); }
.fx-faixa:nth-child(even) { background: var(--bg-alt); }

.fx-foto {
  min-height: 220px;
  background: linear-gradient(130deg, var(--border-alt), var(--bg));
}

.fx-texto { padding: 36px 24px; display: flex; flex-direction: column; justify-content: center; }
.fx-num {
  font-family: 'JetBrains Mono', monospace; font-size: 11px;
  letter-spacing: 0.12em; color: var(--accent); margin-bottom: 10px;
}
.fx-texto h3 { margin: 0 0 10px; font-family: 'Sora', sans-serif; font-size: 20px; }
.fx-texto p { margin: 0; color: var(--text-muted); line-height: 1.6; max-width: 46ch; }

@media (min-width: 1024px) {
  .fx-faixa { grid-template-columns: 1fr 1fr; align-items: stretch; }
  .fx-foto { min-height: 260px; }

  /* O 100% é a largura da PRÓPRIA célula, metade da faixa — por isso funciona
     e por isso 100vw estaria errado: incluiria a barra de rolagem e jogaria o
     texto alguns pixels pro lado. O max() segura o respiro mínimo quando a
     célula fica menor que a coluna. */
  .fx-texto { padding-left: max(24px, calc(100% - 556px)); padding-right: 24px; }

  /* Invertida: a foto vai pra direita e o texto encosta na coluna pelo outro lado. */
  .fx-invertida .fx-foto { order: 2; }
  .fx-invertida .fx-texto {
    order: 1;
    padding-right: max(24px, calc(100% - 556px));
    padding-left: 24px;
    text-align: right;
  }
  .fx-invertida .fx-texto p { margin-left: auto; }
}
